; Input:  None (reads current slot index from 13526)
; Output: XIY = pointer to patch slot data (at 0x94800 + slot*96 + 96)
; Reads the current patch slot index (0-29, capped), multiplies by 96-byte
; stride, and returns a pointer into the accompaniment patch table at 0x94800.
; ============================================================================
AccPatch_GetCurrentSlotAddr:
	lds32	xhl, 0
	ldb_d8	l, (13370)
	cp	l, 30
	jr	c, 2
	ldb	l, 0
AccPatch_GetSlotAddr_Valid:
	mul hl, 0x60
	add xhl, 0x60
	ld xiy, 0x94800
	add xiy, xhl
	ret

AccPatch_GetSlotAddr_Preserve:
	push	xwa
	push	xix
	xor	xhl, xhl
	ldb_d8	l, (13370)
	cp	l, 30
	jr	c, 2
	xor	l, l
	mul	hl, 96
	add	xhl, 96
	ld	xiy, 608256
	add	xiy, xhl
	pop	xix
	pop	xwa
	ret
AccPatch_GetEntryAddr:
	cp hl, 0xffff
	jr z, AccPatch_GetEntryAddr_Ret
	pushw hl
	pushw hl
	lds32 xhl, 0
	popw hl
	sll xhl, 8
	ld xix, 0x95c00
	add xix, xhl
	popw hl

AccPatch_GetEntryAddr_Ret:
	ret

AccPatch_InitCurrentSlot:
	.byte 0x1e, 0xa4, 0xff, 0x1e, 0xe4, 0x00, 0x1e, 0x86
	.byte 0x01, 0x1e, 0x2d, 0x01, 0xc1, 0x31, 0x34, 0x3e
	.byte 0x80, 0x1e, 0xca, 0x11, 0x0e
AccPatch_InitFromSlotIndex:
	push xiz
	calr AccPatch_InitFromIndex
	pop xiz
	ret

AccPatch_InitFromIndex:
	xor	xhl, xhl
	ldb_d8	l, (14608)
	cp	l, 30
	jr	c, 2
	xor	l, l
AccPatch_InitFromIndex_Valid:
	.byte 0xdb, 0x08, 0x60, 0x00, 0xeb, 0xc8, 0x60, 0x00
	.byte 0x00, 0x00, 0xe1, 0x12, 0x39, 0x25, 0xeb, 0x85
	.byte 0x1e, 0x81, 0x0e, 0x1e, 0x29, 0x00, 0x1e, 0xe6
	.byte 0x0e, 0xc1, 0x31, 0x34, 0x3e, 0x80, 0x1e, 0x34
	.byte 0x0f, 0x0e
